mapper.select:
select C.COMPANY_NO ,C.BUSINESS_NO ,C.COMPANY_NAME ,C.REPRESENTATIVE_NAME ,C.PHONE ,C.EMAIL ,C.CREATED_ON ,C.STATUS ,CS_MEMO.MEMO ,S.FIELD from( select * from( select ROWNUM RN, A.* from( select COM.COMPANY_NO ,COM.BUSINESS_NO ,COM.COMPANY_NAME ,COM.REPRESENTATIVE_NAME ,COM.PHONE ,COM.EMAIL ,COM.CREATED_ON ,COM.STATUS from COMPANY COM
and COM.BUSINESS_NO like '%' || #{businessNo} || '%' escape '/'
and COM.COMPANY_NAME like '%' || #{companyName} || '%' escape '/'
and COM.REPRESENTATIVE_NAME like '%' || #{representativeName} || '%' escape '/'
and COM.STATUS = #{status}
and exists ( select 1 from COMPANY_SPECIALTY CS2 inner join SPECIALTY S2 on S2.SPECIALTY_NO = CS2.SPECIALTY_NO where CS2.COMPANY_NO = COM.COMPANY_NO and S2.FIELD = #{option}
and CS2.MEMO like '%' || #{etcMemo} || '%' escape '/'
)
order by COM.COMPANY_NO desc ) A where ROWNUM <= #{endRow} ) B where B.RN >= #{startRow} ) C left join COMPANY_SPECIALTY CS on(CS.COMPANY_NO = C.COMPANY_NO) left join SPECIALTY S on(S.SPECIALTY_NO = CS.SPECIALTY_NO) left join COMPANY_SPECIALTY CS_MEMO on (CS_MEMO.COMPANY_NO = C.COMPANY_NO and CS_MEMO.SPECIALTY_NO = ( select SPECIALTY_NO from SPECIALTY where FIELD = '기타' ))

select count(*) from COMPANY COM
and COM.BUSINESS_NO like '%' || #{businessNo} || '%' escape '/'
and COM.COMPANY_NAME like '%' || #{companyName} || '%' escape '/'
and COM.REPRESENTATIVE_NAME like '%' || #{representativeName} || '%' escape '/'
and COM.STATUS = #{status}
and exists ( select 1 from COMPANY_SPECIALTY CS2 inner join SPECIALTY S2 on S2.SPECIALTY_NO = CS2.SPECIALTY_NO where CS2.COMPANY_NO = COM.COMPANY_NO and S2.FIELD = #{option}
and CS2.MEMO like '%' || #{etcMemo} || '%' escape '/'
)

mapper.update:
update COMPANY
set
  BUSINESS_NO = #{businessNo}
  ,COMPANY_NAME = #{companyName}
  ,REPRESENTATIVE_NAME = #{representativeName}
  ,PHONE = #{phone}
  ,EMAIL = #{email}
  ,CREATED_ON = #{createdOn}
  ,STATUS = #{status}
where COMPANY_NO = #{companyNo}

mapper.select:
select INTRO
from COMPANY
where COMPANY_NO = #{companyNo}

  and STATUS = #{status}

mapper.update:
update COMPANY
set INTRO = #{intro}
where COMPANY_NO = #{companyNo}

mapper.insert:
insert into COMPANY_LOCATION(
  COMPANY_NO, LOCATION_NO, NAME
)values(
  #{companyNo}, #{locationNo}, #{name}
)

mapper.delete:
delete from COMPANY_LOCATION
where LOCATION_NO = #{locationNo}
and COMPANY_NO = #{companyNo}

mapper.select:
select * from( select A.*, rownum RN from( select MS.NAME ,MS.MEMO ,MS.START_ON ,MS.END_ON ,MS.VISIBLE ,MS.STATUS ,L.LOCATION_NO ,L.LATITUDE ,L.LONGITUDE ,L.ADDRESS ,L.SIDO ,L.SIGUNGU from MANAGEMENT_STATUS MS left join LOCATION L on (L.LOCATION_NO = MS.LOCATION_NO) where MS.COMPANY_NO = #{companyNo}
and MS.VISIBLE = 'ALL'
order by MS.START_ON desc ) A where rownum <= #{endRow} ) B where RN >= #{startRow}

mapper.delete:
delete from LOCATION
where LOCATION_NO = (
  select LOCATION_NO
  from MANAGEMENT_STATUS
  where COMPANY_NO = #{companyNo}
  and LOCATION_NO = #{locationNo}
)

mapper.update:
update MANAGEMENT_STATUS
set
  LOCATION_NO = #{location.locationNo}
  ,NAME = #{name}
  ,MEMO = #{memo}
  ,START_ON = #{startOn}
  ,END_ON = #{endOn}
  ,VISIBLE = #{visible}
  ,STATUS = #{status}
where COMPANY_NO = #{companyNo}
